// Independently implemented device-validation pipeline. See PROVENANCE.md.
#import "OBNativeNACValidator.h"
#import "OBAbsintheIPC.h" // Generated by the Apple SDK mig tool, never checked in.
#import <mach/mach.h>
#import <mach/task_special_ports.h>
#import <dlfcn.h>
#import <stdint.h>

enum { OBNACMaximumData = 16384, OBNACMaximumHTTP = 65536 };
static const uint32_t OBNACProtocolWord = 0x50936603;
static double OBNACNow(void) { return NSProcessInfo.processInfo.systemUptime; }
// The iOS SDK omits servers/bootstrap.h. Resolve only this fixed system ABI,
// checked against Apple's launchd bootstrap.h, rather than importing Mac headers.
typedef kern_return_t (*OBNACServiceLookup)(mach_port_t, const char *, mach_port_t *);

// Clear only the exact out-of-line allocation returned by the kernel/MIG call.
static NSData *OBNACConsume(vm_offset_t pointer, mach_msg_type_number_t count) {
    NSData *copy = nil;
    if (pointer && count && count <= OBNACMaximumData)
        copy = [NSData dataWithBytes:(const void *)pointer length:count];
    if (pointer && count) {
        volatile uint8_t *bytes = (volatile uint8_t *)pointer;
        for (mach_msg_type_number_t i = 0; i < count; ++i) bytes[i] = 0;
        vm_deallocate(mach_task_self(), pointer, count);
    }
    return copy;
}

@interface OBNACHTTPExchange : NSObject <NSURLSessionTaskDelegate>
@property(nonatomic, strong) NSURLSession *session;
@property(nonatomic, strong) NSLock *lock;
@property(nonatomic, strong) dispatch_semaphore_t ready;
@property(nonatomic, strong) NSData *result;
@property(nonatomic) BOOL finished;
- (NSData *)fetchURL:(NSURL *)url body:(NSData *)body deadline:(double)deadline;
@end

@implementation OBNACHTTPExchange
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task
    willPerformHTTPRedirection:(NSHTTPURLResponse *)response
                    newRequest:(NSURLRequest *)request
             completionHandler:(void (^)(NSURLRequest *))completionHandler {
    (void)session; (void)task; (void)response; (void)request;
    // Never forward the validation-session request to a redirect target.
    completionHandler(nil);
}

- (NSData *)fetchURL:(NSURL *)url body:(NSData *)body deadline:(double)deadline {
    if (![url.scheme isEqualToString:@"https"] || OBNACNow() >= deadline) return nil;
    self.lock = [NSLock new];
    self.ready = dispatch_semaphore_create(0);
    NSTimeInterval remaining = MIN(8.0, deadline - OBNACNow());
    if (remaining <= 0) return nil;
    NSURLSessionConfiguration *configuration = NSURLSessionConfiguration.ephemeralSessionConfiguration;
    configuration.URLCache = nil;
    configuration.HTTPCookieStorage = nil;
    configuration.HTTPShouldSetCookies = NO;
    configuration.timeoutIntervalForRequest = remaining;
    configuration.timeoutIntervalForResource = remaining;
    self.session = [NSURLSession sessionWithConfiguration:configuration delegate:self delegateQueue:nil];
    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url
        cachePolicy:NSURLRequestReloadIgnoringLocalCacheData timeoutInterval:remaining];
    request.HTTPMethod = body ? @"POST" : @"GET";
    request.HTTPBody = body;
    [request setValue:@"application/x-apple-plist" forHTTPHeaderField:@"Accept"];
    if (body) [request setValue:@"application/x-apple-plist" forHTTPHeaderField:@"Content-Type"];
    NSURLSessionDataTask *task = [self.session dataTaskWithRequest:request
        completionHandler:^(NSData *data, NSURLResponse *response, NSError *error) {
        [self.lock lock];
        if (!self.finished) {
            self.finished = YES;
            BOOL valid = !error && OBNACNow() < deadline
                && [response isKindOfClass:NSHTTPURLResponse.class]
                && [(NSHTTPURLResponse *)response statusCode] == 200
                && [response.URL isEqual:url]
                && [data isKindOfClass:NSData.class] && data.length > 0 && data.length <= OBNACMaximumHTTP;
            if (valid) self.result = data;
            dispatch_semaphore_signal(self.ready);
        }
        [self.lock unlock];
    }];
    [task resume];
    dispatch_semaphore_wait(self.ready,
        dispatch_time(DISPATCH_TIME_NOW, (int64_t)(remaining * NSEC_PER_SEC)));
    [self.lock lock];
    self.finished = YES;
    NSData *result = self.result;
    self.result = nil;
    [self.lock unlock];
    [task cancel];
    [self.session invalidateAndCancel];
    self.session = nil;
    return OBNACNow() < deadline ? result : nil;
}
@end

static NSDictionary *OBNACPlist(NSData *data) {
    if (!data || data.length > OBNACMaximumHTTP) return nil;
    id value = [NSPropertyListSerialization propertyListWithData:data
        options:NSPropertyListImmutable format:NULL error:NULL];
    return [value isKindOfClass:NSDictionary.class] ? value : nil;
}

static NSData *OBNACData(id value) {
    return [value isKindOfClass:NSData.class] && [value length] > 0
        && [value length] <= OBNACMaximumData ? value : nil;
}

@interface OBNativeNACValidator ()
@property(nonatomic, strong) dispatch_queue_t nativeQueue;
@property(atomic, copy, readwrite) NSString *lastFailureCode;
@end

@implementation OBNativeNACValidator
- (instancetype)init {
    if ((self = [super init])) {
        _nativeQueue = dispatch_queue_create("dev.openbubbles.relay.native.device-validation", DISPATCH_QUEUE_SERIAL);
        _lastFailureCode = @"not-requested";
    }
    return self;
}

- (NSData *)validationUntil:(double)deadline {
    if (OBNACNow() >= deadline) { self.lastFailureCode = @"deadline"; return nil; }
    NSURL *certificateURL = [NSURL URLWithString:@"https://static.ess.apple.com/identity/validation/cert-1.0.plist"];
    NSData *certificateReply = [[OBNACHTTPExchange new] fetchURL:certificateURL body:nil deadline:deadline];
    if (!certificateReply) { self.lastFailureCode = @"certificate-transport"; return nil; }
    NSData *certificate = OBNACData(OBNACPlist(certificateReply)[@"cert"]);
    if (!certificate) { self.lastFailureCode = @"certificate-shape"; return nil; }
    OBNACServiceLookup lookup = (OBNACServiceLookup)dlsym(RTLD_DEFAULT, "bootstrap_look_up");
    mach_port_t bootstrap = MACH_PORT_NULL;
    if (!lookup || task_get_bootstrap_port(mach_task_self(), &bootstrap) != KERN_SUCCESS
        || bootstrap == MACH_PORT_NULL) {
        if (bootstrap != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), bootstrap);
        self.lastFailureCode = @"native-bootstrap"; return nil;
    }
    mach_port_t service = MACH_PORT_NULL;
    kern_return_t lookupStatus = lookup(bootstrap, "com.apple.absd", &service);
    mach_port_deallocate(mach_task_self(), bootstrap);
    if (lookupStatus != KERN_SUCCESS || service == MACH_PORT_NULL) {
        if (service != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), service);
        self.lastFailureCode = @"native-service"; return nil;
    }
    @try {
        uint64_t handle = 0;
        vm_offset_t challengePointer = 0;
        mach_msg_type_number_t challengeCount = 0;
        if (OBNACNow() >= deadline) { self.lastFailureCode = @"deadline"; return nil; }
        kern_return_t status = OBAbsintheBeginSession(service, OBNACProtocolWord,
            (vm_offset_t)certificate.bytes, (mach_msg_type_number_t)certificate.length,
            &handle, &challengePointer, &challengeCount);
        NSData *challenge = OBNACConsume(challengePointer, challengeCount);
        if (status != KERN_SUCCESS || !challenge) { self.lastFailureCode = @"native-init"; return nil; }
        if (OBNACNow() >= deadline) { self.lastFailureCode = @"deadline"; return nil; }
        NSData *body = [NSPropertyListSerialization dataWithPropertyList:@{@"session-info-request":challenge}
            format:NSPropertyListXMLFormat_v1_0 options:0 error:NULL];
        if (!body) { self.lastFailureCode = @"session-request"; return nil; }
        NSURL *sessionURL = [NSURL URLWithString:@"https://identity.ess.apple.com/WebObjects/TDIdentityService.woa/wa/initializeValidation"];
        NSData *sessionReply = [[OBNACHTTPExchange new] fetchURL:sessionURL body:body deadline:deadline];
        if (!sessionReply) { self.lastFailureCode = @"session-transport"; return nil; }
        NSData *sessionInfo = OBNACData(OBNACPlist(sessionReply)[@"session-info"]);
        if (!sessionInfo) { self.lastFailureCode = @"session-shape"; return nil; }
        if (OBNACNow() >= deadline) { self.lastFailureCode = @"deadline"; return nil; }
        status = OBAbsintheEstablishSession(service, OBNACProtocolWord, handle,
            (vm_offset_t)sessionInfo.bytes, (mach_msg_type_number_t)sessionInfo.length);
        if (status != KERN_SUCCESS) { self.lastFailureCode = @"native-key-establishment"; return nil; }
        if (OBNACNow() >= deadline) { self.lastFailureCode = @"deadline"; return nil; }
        vm_offset_t signaturePointer = 0;
        mach_msg_type_number_t signatureCount = 0;
        // Sign empty bytes in the DEVICE NAC session. Never AAAbsintheSigner.
        status = OBAbsintheSignBytes(service, OBNACProtocolWord, handle, 0, 0,
            &signaturePointer, &signatureCount);
        NSData *signature = OBNACConsume(signaturePointer, signatureCount);
        if (status != KERN_SUCCESS || !signature) { self.lastFailureCode = @"native-sign"; return nil; }
        if (OBNACNow() >= deadline) { self.lastFailureCode = @"deadline"; return nil; }
        self.lastFailureCode = @"none";
        return signature;
    } @finally {
        mach_port_deallocate(mach_task_self(), service);
    }
}

- (void)generateValidationDataWithDeadline:(double)deadline completion:(void (^)(NSData *))completion {
    dispatch_async(self.nativeQueue, ^{
        @autoreleasepool {
            NSData *result = nil;
            @try { result = [self validationUntil:deadline]; }
            @catch (NSException *exception) {
                (void)exception;
                self.lastFailureCode = @"native-exception";
            }
            completion(result);
        }
    });
}
@end
